const b = ($json && $json.body) ? $json.body : ($json || {});
const s = (k) => { const v = b[k]; return v == null ? '' : String(v).trim(); };
const num = (k) => { const v = parseFloat(String(b[k] == null ? '' : b[k]).replace(/[^0-9.]/g, '')); return isNaN(v) ? null : v; };
const name = s('name') || s('contactName') || s('fullName') || 'عميل';
const email = s('email');
const phone = s('phone') || s('mobile');
const notes = s('notes') || s('message') || s('details') || s('requirements');
const cityRaw = (s('city')).toLowerCase();
const cityEn = { riyadh: 'Riyadh', jeddah: 'Jeddah', jedda: 'Jeddah', dammam: 'Dammam', khobar: 'Khobar', makkah: 'Makkah', mecca: 'Makkah', madinah: 'Madinah', medina: 'Madinah' };
const cityAr = { 'الرياض': 'Riyadh', 'جدة': 'Jeddah', 'جده': 'Jeddah', 'الدمام': 'Dammam', 'الخبر': 'Khobar', 'مكة': 'Makkah', 'مكه': 'Makkah', 'المدينة': 'Madinah', 'المدينه': 'Madinah' };
let city = cityEn[cityRaw] || cityAr[s('city')] || '';
if (!city) { for (const k in cityEn) { if (cityRaw.indexOf(k) >= 0) { city = cityEn[k]; break; } } }
if (!city && s('city')) { for (const k in cityAr) { if (s('city').indexOf(k) >= 0) { city = cityAr[k]; break; } } }
if (!city) city = 'Other';
const catRaw = (s('category') || s('propertyCategory') || s('type') || '').toLowerCase();
const catPairs = [['coworking', 'Co-working Space'], ['co-working', 'Co-working Space'], ['مشترك', 'Co-working Space'], ['office', 'Office'], ['مكتب', 'Office'], ['commercial', 'Commercial'], ['تجاري', 'Commercial'], ['retail', 'Retail'], ['محل', 'Retail'], ['showroom', 'Showroom'], ['معرض', 'Showroom'], ['warehouse', 'Industrial'], ['industrial', 'Industrial'], ['مستودع', 'Industrial'], ['صناعي', 'Industrial'], ['factory', 'Factory'], ['مصنع', 'Factory'], ['land', 'Land'], ['ارض', 'Land'], ['أرض', 'Land'], ['residential', 'Residential'], ['سكني', 'Residential'], ['villa', 'Residential'], ['فيلا', 'Residential']];
let category = '';
for (const p of catPairs) { if (catRaw.indexOf(p[0]) >= 0) { category = p[1]; break; } }
if (!category) category = 'Office';
const size = num('size') || num('sizeSqm') || num('area');
const seats = num('seats') || num('capacity') || num('people') || num('persons');
const budget = num('budget') || num('price');
const summaryParts = [];
if (seats) summaryParts.push('السعة: ' + seats + ' شخص');
if (size) summaryParts.push('المساحة: ' + size + ' م²');
if (budget) summaryParts.push('الميزانية: ' + budget + ' ريال');
if (notes) summaryParts.push('ملاحظات: ' + notes);
const aiSummary = summaryParts.join(' · ');
const title = 'طلب عقاري — ' + city + ' — ' + name;
return { json: { name, email, phone, city, category, size, seats, budget, notes, aiSummary, title, hasEmail: email !== '' } };

